<summary>proof source</summary>

```ts
import { describe, expect, it, vi } from "vitest";

const { fetchWithSsrFGuardMock } = vi.hoisted(() => ({
  fetchWithSsrFGuardMock: vi.fn(),
}));

vi.mock("openclaw/plugin-sdk/ssrf-runtime", () => ({
  fetchWithSsrFGuard: fetchWithSsrFGuardMock,
  ssrfPolicyFromHttpBaseUrlAllowedHostname: (baseUrl: string) => ({
    allowedHostnames: [new URL(baseUrl).hostname],
  }),
}));

import { discoverKilocodeModels } from "./extensions/kilocode/provider-models.js";

describe("Kilocode discovery proof", () => {
  it("keeps the valid model path working", async () => {
    vi.stubEnv("NODE_ENV", "");
    vi.stubEnv("VITEST", "");
    fetchWithSsrFGuardMock.mockResolvedValue({
      release: vi.fn(async () => {}),
      response: new Response(
        JSON.stringify({
          data: [
            {
              id: "vendor/model",
              name: "Vendor Model",
              context_length: 8192,
              pricing: { prompt: "0.000001", completion: "0.000002" },
            },
          ],
        }),
        { status: 200, headers: { "content-type": "application/json" } },
      ),
    });

    await expect(discoverKilocodeModels()).resolves.toEqual(
      expect.arrayContaining([expect.objectContaining({ id: "vendor/model" })]),
    );
  });

  it("cancels failed discovery bodies before static fallback", async () => {
    vi.stubEnv("NODE_ENV", "");
    vi.stubEnv("VITEST", "");
    const cancel = vi.fn();
    fetchWithSsrFGuardMock.mockResolvedValue({
      release: vi.fn(async () => {}),
      response: new Response(
        new ReadableStream({
          start(controller) {
            controller.enqueue(new TextEncoder().encode("temporary failure"));
          },
          cancel,
        }),
        { status: 500 },
      ),
    });

    await expect(discoverKilocodeModels()).resolves.toEqual(
      expect.arrayContaining([expect.objectContaining({ id: "kilo-auto/balanced" })]),
    );
    expect(cancel).toHaveBeenCalledOnce();
  });
});
```

